<script>
(()=>{const panel=document.querySelector('#dnct-support-chat-panel'),button=document.querySelector('#dnct-support-chat-btn');if(!panel||!button)return;const csrf=<?php echo json_encode(csrf_token());?>,groups=<?php echo json_encode($groups,JSON_UNESCAPED_UNICODE);?>,prefill={name:<?php echo json_encode($name);?>,email:<?php echo json_encode($email);?>};let current=null,activeTab='alerts',lastSignature='';
const esc=s=>{const e=document.createElement('span');e.textContent=s;return e.innerHTML};const key=()=>{const b=new Uint8Array(32);crypto.getRandomValues(b);return [...b].map(x=>x.toString(16).padStart(2,'0')).join('')};const post=body=>{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),10000);return fetch("/api/support/ticket.php",{method:"POST",headers:{"Content-Type":"application/json","X-CSRF-Token":csrf},body:JSON.stringify({...body,csrf_token:csrf}),signal:controller.signal}).then(async r=>{const data=await r.json().catch(()=>({ok:false,message:"Serwer zwrócił nieprawidłową odpowiedź."}));return r.ok?data:{...data,ok:false}}).finally(()=>clearTimeout(timer))};const close=()=>{panel.classList.remove('is-open');panel.setAttribute('aria-hidden','true');button.setAttribute('aria-expanded','false')};
function shell(){panel.dataset.csrf=csrf;panel.innerHTML='<div class="dnct-support-chat-topbar"><span class="dnct-support-chat-dots"><i></i><i></i><i></i></span><p><span>support</span> — centrum pomocy</p><button id="dnct-ticket-close" type="button" class="dnct-support-chat-close" aria-label="Zamknij">×</button></div><div class="dnct-ticket-tabs"><button data-tab="alerts">Powiadomienia</button><button data-tab="support">Wsparcie</button></div><div class="dnct-support-chat-body" id="dnct-ticket-body"></div>';panel.querySelector('#dnct-ticket-close').onclick=close;panel.querySelectorAll('[data-tab]').forEach(x=>x.onclick=()=>{activeTab=x.dataset.tab;panel.querySelectorAll('[data-tab]').forEach(y=>y.classList.toggle('is-active',y===x));refresh()});panel.querySelector('[data-tab="alerts"]').classList.add('is-active');refresh()}
function refresh(){if(activeTab==='alerts'){alerts();return}fetch('/api/support/ticket.php').then(r=>r.json()).then(render).catch(()=>panel.querySelector('#dnct-ticket-body').textContent='Nie udało się wczytać rozmowy.')}
function alerts(){const out=panel.querySelector('#dnct-ticket-body');out.innerHTML='<p class="dnct-cli-muted">$ tail powiadomienia…</p>';
const kiedy=t=>{const d=new Date(String(t||'').replace(' ','T'));if(isNaN(d))return '';const p=n=>String(n).padStart(2,'0');return p(d.getDate())+'.'+p(d.getMonth()+1)+' '+p(d.getHours())+':'+p(d.getMinutes())};
fetch('/api/notifications/list.php').then(r=>r.json()).then(d=>{const lista=d.notifications||[];out.innerHTML='<div class="dnct-ticket-scroll dnct-cli-log" aria-live="polite">'+(lista.map(n=>'<div class="dnct-cli-entry'+(n.is_read?'':' is-new')+'" data-id="'+Number(n.id)+'"><button type="button" class="dnct-cli-x" aria-label="Usuń powiadomienie" title="Usuń">×</button><span class="dnct-cli-time">['+esc(kiedy(n.created_at))+']</span> <b>'+esc(n.title)+'</b><span class="dnct-cli-msg">'+esc(n.message)+'</span></div>').join('')||'<p class="dnct-cli-muted">brak powiadomień_</p>')+'</div>';
out.querySelectorAll('.dnct-cli-x').forEach(x=>x.onclick=()=>{const row=x.closest('.dnct-cli-entry');row.classList.add('is-gone');fetch('/api/notifications/hide.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':csrf},body:JSON.stringify({id:Number(row.dataset.id),csrf_token:csrf})}).then(r=>{if(!r.ok)throw 0;setTimeout(()=>{row.remove();if(!out.querySelector('.dnct-cli-entry'))out.querySelector('.dnct-cli-log').innerHTML='<p class="dnct-cli-muted">brak powiadomień_</p>'},180)}).catch(()=>row.classList.remove('is-gone'))})}).catch(()=>out.innerHTML='<p class="dnct-cli-muted">zaloguj się, aby zobaczyć powiadomienia_</p>')}
const sentLabel=m=>m.author_role==="customer"&&Date.now()-Date.parse(String(m.created_at||"").replace(" ","T"))<30000?"<small class=\"dnct-message-state\">Wysłano</small>":"";let replyTo=null;const replyQuote=m=>{if(!m.reply_to_message_id)return "";const target=esc(m.reply_author_name||"użytkownik");const isSelfReply=m.author_role==="customer"&&String(m.reply_author_name||"")===String(m.author_name||"");const label=m.author_role==="customer"?(isSelfReply?"Odpowiedziałeś(aś) sobie":`Odpowiedziałeś(aś) ${target}`):`${esc(m.author_name||"Administracja")} odpowiedział(a) Ci`;return `<p class="dnct-reply-context">${label}</p><div class="dnct-replied-bubble">${esc(m.reply_body||"")}</div>`};const replyPreview=()=>replyTo?`<div class="dnct-reply-preview"><input type="hidden" name="reply_to_id" value="${Number(replyTo.id)||0}"><span><b>Odpowiadasz: ${esc(replyTo.author_name||"Wiadomość")}</b>${esc(replyTo.body||"")}</span><button type="button" class="dnct-cancel-reply" aria-label="Anuluj odpowiedź">×</button></div>`:"";function messages(data){return `<div class="dnct-ticket-thread" aria-live="polite"><p class="dnct-ticket-day">Dzisiaj</p>`+data.messages.map(m=>`<div class="dnct-ticket-row `+(m.author_role==="customer"?"mine":"admin")+`" data-message-id="${m.id}"><div class="dnct-ticket-bubble-wrap">${replyQuote(m)}<div class="dnct-ticket-message-line"><button type="button" class="dnct-message-reply" data-reply-id="${m.id}" aria-label="Odpowiedz">↩</button><div class="dnct-ticket-bubble"><span class="dnct-ticket-author">`+(m.author_role==="customer"?"":(m.author_name||"Administracja"))+`</span>`+esc(m.body)+sentLabel(m)+`</div></div></div></div>`).join("")+`</div>`}function bindReplyActions(data,out){out.querySelectorAll(".dnct-message-reply").forEach(button=>button.onclick=()=>{replyTo=(data.messages||[]).find(m=>String(m.id)===button.dataset.replyId)||null;lastSignature="";render(data)});out.querySelector(".dnct-cancel-reply")?.addEventListener("click",()=>{replyTo=null;lastSignature="";render(data)})}
function render(data){const out=panel.querySelector('#dnct-ticket-body');const previous=current;const previousStatus=previous ? previous.status : '';if(!data.ticket&&previous)return;current=data.ticket;if(current && previousStatus==='new' && current.status==='open'){panel.classList.add('is-open');panel.setAttribute('aria-hidden','false');button.setAttribute('aria-expanded','true')}if(!current){if(out.querySelector(".dnct-ticket-form"))return;let options='<option value="" disabled selected>W czym możemy Ci pomóc?</option>';Object.entries(groups).forEach(([g,items])=>{options+='<optgroup label="'+esc(g)+'">';Object.entries(items).forEach(([k,n])=>options+='<option value="'+esc(k)+'">'+esc(n)+'</option>');options+='</optgroup>'});out.innerHTML='<form class="dnct-ticket-form" action="#" onsubmit="return false"><label>Imię<input required name="name" maxlength="60" value="'+esc(prefill.name)+'"></label><label>Adres e-mail<input required name="email" type="email" value="'+esc(prefill.email)+'"></label><label>Potrzebuję pomocy<select required name="category">'+options+'</select></label><label>Wiadomość<textarea required name="message" minlength="20" maxlength="2000" placeholder="Wprowadź swoją wiadomość"></textarea></label><input name="website" tabindex="-1" style="position:absolute;left:-9999px"><p class="dnct-ticket-error" hidden></p><button class="dnct-ticket-action">Rozpocznij rozmowę</button></form>';out.querySelector('form').addEventListener('submit',e=>{e.preventDefault();const form=e.currentTarget,send=form.querySelector('button'),err=form.querySelector('p');if(!form.reportValidity())return;send.disabled=true;send.textContent='Wysyłanie…';post({action:'create',...Object.fromEntries(new FormData(form)),request_key:key()}).then(x=>{if(!x.ok){err.textContent=x.message+(x.errors&&Object.keys(x.errors).length?' '+Object.values(x.errors).join(' '):'');err.hidden=false;send.disabled=false;send.textContent='Rozpocznij rozmowę';return}render(x)}).catch(()=>{err.textContent='Błąd połączenia.';err.hidden=false;send.disabled=false;send.textContent='Rozpocznij rozmowę'})});const ticketForm=out.querySelector("form"),ticketButton=ticketForm.querySelector("button");ticketButton.type="button";ticketButton.onclick=()=>ticketForm.dispatchEvent(new Event("submit",{cancelable:true}));return}
const sig=current.id+":"+current.status+":"+data.messages.length;const hasRecentSent=(data.messages||[]).some(m=>m.author_role==="customer"&&Date.now()-Date.parse(String(m.created_at||"").replace(" ","T"))<30000);if(sig===lastSignature&&out.querySelector(".dnct-ticket-conversation")&&!hasRecentSent)return;lastSignature=sig;if(current.status!=="open"||!current.assigned_admin){out.innerHTML=`<div class="dnct-ticket-conversation">`+messages(data)+`<p class="dnct-ticket-state">Zgłoszenie zostało wysłane. Czekasz, aż administrator przypisze je do siebie. Wtedy otworzy się aktywna rozmowa.</p></div>`;bindReplyActions(data,out);const liveScroll=out.querySelector(".dnct-ticket-thread");if(liveScroll)liveScroll.scrollTop=liveScroll.scrollHeight;return}out.innerHTML=`<div class="dnct-ticket-conversation">`+messages(data)+`<form id="dnct-ticket-reply" class="dnct-ticket-composer">`+replyPreview()+`<textarea class="dnct-ticket-reply" required maxlength="2000" placeholder="Wpisz treść wiadomości"></textarea></form></div>`;bindReplyActions(data,out);const liveScroll=out.querySelector(".dnct-ticket-thread");if(liveScroll)liveScroll.scrollTop=liveScroll.scrollHeight;out.querySelector("#dnct-ticket-reply").addEventListener("submit",e=>{e.preventDefault();const form=e.currentTarget,field=form.querySelector("textarea"),body=field.value.trim();if(!body)return;post({action:"message",ticket_id:current.id,message:body,message_key:key(),reply_to_id:replyTo?replyTo.id:0}).then(x=>{if(x.ok){replyTo=null;field.value="";render(x)}})})}
panel.addEventListener("dnct:reply-sent",()=>{replyTo=null;lastSignature="";refresh()});shell();panel.addEventListener("keydown",e=>{if(e.key==="Enter"&&!e.shiftKey&&e.target.matches("#dnct-ticket-reply textarea")){e.preventDefault();e.target.closest("form").dispatchEvent(new Event("submit",{cancelable:true,bubbles:true}))}});panel.addEventListener("submit",e=>e.preventDefault());panel.addEventListener("wheel",e=>e.stopPropagation(),{passive:true});panel.addEventListener("pointerdown",e=>e.stopPropagation());button.addEventListener('click',()=>{if(panel.classList.contains('is-open'))refresh()});setInterval(()=>{if(activeTab==='support')refresh()},1000)})();
</script>
